on>
<script>const placeholders = {'Bulk palm oil':'Product, approximate volume, delivery location and timing…','Seedlings':'Number of seedlings, planting location and when you plan to plant…','Partnership / investment':'Your organisation and the kind of partnership you have in mind…','Media':'Your publication and what you are working on…','Other':'How can we help?'}; document.querySelectorAll('.type-chips button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.type-chips button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.querySelector('input[name=subject]').value=b.dataset.type;document.querySelector('textarea[name=message]').placeholder=placeholders[b.dataset.type]}); document.querySelector('.type-chips button.selected')?.click();</script>
